41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	};
51	
52	const premiumFor = (quote: QuoteStep): number => {
53	  const policyBase = quote.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
54	  return Math.ceil(policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
55	};
56	
57	const resultOf = (step: Step): StepResult => {
58	  if (step.op === "quote") return { premium: premiumFor(step) };
59	  throw new Error(`unsupported step: ${step.op}`);
60	};
61	
62	export const runScenario = (scenario: Scenario): ScenarioResult => ({
63	  results: scenario.steps.map(resultOf),
64	});
